/// [RenamableFileSystem] (atomic swap) — anything else fails with
/// [SessionRepairErrorCode.unsupported] rather than half-applying.
Future<SessionRepairReport> repairSessionLedgers(
  FileSystem fs,
  String path, {
  bool dryRun = false,
  Set<String>? dropTypes,
  Set<String>? keepLatestTypes,
}) async {
  final drops = dropTypes ?? repairDropCustomTypes;
  final keepLatest = keepLatestTypes ?? repairKeepLatestCustomTypes;
  final (:ranged, :renamable) = _repairIoSurface(fs);
  final stat = await fs.fileInfo(path);
  if (stat.isErr) {
    final code = stat.errorOrNull!.code == FileErrorCode.notFound
        ? SessionRepairErrorCode.notFound
        : SessionRepairErrorCode.unknown;
    throw SessionRepairException(
      'cannot stat session file $path: ${stat.errorOrNull!.message}',
      code: code,
    );
  }
  final bytesBefore = stat.valueOrNull!.size;

  // Rotated segment siblings (gh-1077: `<file>.part-NN` holds the records
  // rotated out of the primary). Repair rewrites ONLY the primary — the
  // count goes into the report so the bytesBefore/bytesAfter line cannot
  // overstate the on-disk reduction. A listing hiccup must not fail the
  // repair: the note degrades to "parts unknown".
  final untouchedSegments = await _countPartSiblings(fs, path);

  // Pass 1: classify every line by byte span. Nothing is decoded whole —
  // a 12 GiB file scans in bounded chunks.
  final scan = _RepairLedgerScan(path, drops, keepLatest);
  await SessionLineScanner(
    fs: fs,
    path: path,
  ).scan(scan.handleLine, fileSize: bytesBefore);

  // The LATEST snapshot of each keep-latest type joins the kept spans, in
  // file position order — one record each.
  final keptSpans = scan.finishSpans();
  final recordsKept = scan.keptRecords + scan.latestByType.length;
  // gh-1590: the dry run reports the size the rewrite would give — the
  // exact byte sum of the spans pass 2 would stream, so `--dry-run` and
  // the real pass agree on the same fixture.
  final projectedBytesAfter = [
    ...scan.headerSpan,
    ...keptSpans,
  ].fold<int>(0, (sum, span) => sum + (span.$2 - span.$1));

  if (dryRun) {
    return SessionRepairReport(
      path: path,
      recordsRead: scan.recordsRead,
      recordsKept: recordsKept,
      droppedByType: scan.droppedByType,
      droppedBytesByType: scan.droppedBytesByType,
      keptLatestByType: scan.keptLatestByType,
      bytesBefore: bytesBefore,
      bytesAfter: projectedBytesAfter,
      backupPath: '$path.bak',
      dryRun: true,
      untouchedSegments: untouchedSegments,
    );
  }

  // Pass 2: stream the kept spans into a temp file, then swap atomically.
  final bytesAfter = await _writeRepairedAndSwap(
    fs,
    ranged,
    renamable,
    path,
    scan.headerSpan.followedBy(keptSpans),
  );
  return SessionRepairReport(
    path: path,
    recordsRead: scan.recordsRead,
    recordsKept: recordsKept,
    droppedByType: scan.droppedByType,
    droppedBytesByType: scan.droppedBytesByType,
    keptLatestByType: scan.keptLatestByType,
    bytesBefore: bytesBefore,
    bytesAfter: bytesAfter,
    backupPath: '$path.bak',
    dryRun: false,
    untouchedSegments: untouchedSegments,

  }
}

/// The opt-in keep-latest vacuum at session open (issue #1882 AC2):
/// with `sessions.vacuumLedgers: true`, drop the resumed session's
/// superseded `shell_job_registry` / `subagent_registry` /
/// `obligations_ledger` snapshots. The surgery is the SAME
/// [repairSessionLedgers] `fa session repair` performs — MINUS the
/// full-drop ledger types (`model_request_summary`, the trajectory
/// blobs): a resume-time vacuum reclaims dead SNAPSHOTS only; dropping
/// request summaries is the explicit `fa session repair` deep clean,
/// never an automatic side effect (issue #1882 review coherence — PR1
/// bounded those records at ≤ 20 KB, and the Request tab plus the
/// usage-estimation basis live in them). Everything else matches the
/// verb: newest snapshot per ledger kept, everything else byte-
/// verbatim, pre-vacuum bytes preserved at `<path>.bak`, atomic swap.
/// Never a silent default: the config flag is the explicit opt-in, the
/// report lands as a dim line plus a `[vacuum]` fa.log entry. Guards:
/// a live presence row means another instance holds the session — skip
/// (this process registers its own row only after the load); a
/// filesystem without the ranged-read/atomic-rename surface, or any
/// failure, logs and leaves the file untouched. Runs before the
/// warm-switch fingerprint so the cache keys the post-vacuum bytes.
Future<void> _vacuumLedgersAtOpen(SessionMetadata metadata) async {
  final sessions = config.sessionsRetention;
  if (sessions == null || !sessions.vacuumLedgers) return;
  final presenceRows = await config.presenceStore?.list() ?? const {};
  if (presenceRows.containsKey(metadata.id)) {
    _logDiagnostic(
      '[vacuum] skipped ${metadata.id}: another instance holds the '
      'session (live presence row)',
    );
    return;
  }
  SessionRepairReport report;
  try {
    report = await repairSessionLedgers(
      _env,
      metadata.path,
      dropTypes: const {},
    );
  } on Object catch (error) {
    _logDiagnostic('[vacuum] failed for ${metadata.id}: $error');
    return;
  }
  final droppedTotal = report.droppedByType.values.fold<int>(
    0,
    (a, b) => a + b,
  );
  if (droppedTotal == 0) return;
  final reclaimed = report.bytesBefore - report.bytesAfter;
  final ledgerParts = [
    for (final MapEntry(key: type, value: count)
        in report.droppedByType.entries)
      '$type ×$count',
  ].join(', ');
  final line =
      'vacuum: dropped $droppedTotal superseded ledger snapshots '
      '($ledgerParts), reclaimed $reclaimed bytes '
      '(${report.bytesBefore} → ${report.bytesAfter}); '
      'original at ${report.backupPath}';
  io.writeln(_style.dim(line));
  _logDiagnostic('[vacuum] $line');
}

/// Stores a freshly built context for the warm-switch cache only when
